import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
    visibility: "org",
    leadId: owner.id,
    color: "#6366f1",
    targetDate: null,
  });

  return {
    org,
    project,
    actors: actors as Readonly<Record<Role, Actor>>,
    userIds: userIds as Readonly<Record<Role, UserId>>,
  };
}

/** Minimal `CreateIssueInput` with the schema's defaults already applied. */
export function issueInput(
  orgId: OrgId,
  projectId: Project["id"],
  overrides: Partial<{
    title: string;
    assigneeId: UserId | null;
    dueAt: string | null;
  }> = {},
) {
  return {
    orgId,
    projectId,
    title: overrides.title ?? "Ship the thing",
    description: null,
    status: "backlog" as const,
    priority: "none" as const,
    assigneeId: (overrides.assigneeId ?? null) as UserId | null,
    parentId: null,
    estimate: null,
    dueAt: (overrides.dueAt ?? null) as never,
    labelIds: [],
  };
}
import "@testing-library/jest-dom/vitest";
/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}
/**
 * Result envelope every job returns to the scheduler.
 */
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type JobResult = {
  kind: string;
  processed: number;
  failed: number;
  durationMs: number;
  startedAt: IsoTimestamp;
};

/** The zero value a job starts from and mutates as it works. */
export function emptyJobResult(
  kind: string,
  startedAt: IsoTimestamp,
): JobResult {
  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };
}

/**
 * Convenience for a job body: stamps the start, runs the work and fills in
 * `durationMs`. Kept here so every job reports the same shape.
 */
export async function runJob(
  kind: string,
  work: (result: JobResult) => Promise<void>,
): Promise<JobResult> {
  const startedAt = toIsoTimestamp(new Date());
  const began = Date.now();
  const result = emptyJobResult(kind, startedAt);

  await work(result);

  return { ...result, durationMs: Date.now() - began };
}
